  const walked = [];
  let cursor;
  let pages = 0;
  do {
    const page = cursor === undefined
      ? handler.list({ tenant: 'a', limit: 2 })
      : handler.list({ tenant: 'a', limit: 2, cursor });
    walked.push(...page.items.map(x => x.id));
    cursor = page.nextCursor ?? undefined;
    pages++;
    assert.ok(pages < 20, 'pagination did not terminate');
  } while (cursor !== undefined);
  // Lexicographic: 'B' < 'b' < 'c' < 'd' on equal dates.
  assert.deepEqual(walked, ['B', 'b', 'c', 'd', 'a', 'e']);

  // Last page has null nextCursor; exact-fit page also null.
  assert.equal(handler.list({ tenant: 'a', limit: 6 }).nextCursor, null);
  assert.equal(handler.list({ tenant: 'a', limit: 100 }).nextCursor, null);
  const first = handler.list({ tenant: 'a', limit: 2 });
  assert.equal(first.nextCursor, '2026-01-01|b');

  // Cursor resumes strictly after the pair even if that row is not in the data.
  const ghost = handler.list({ tenant: 'a', limit: 10, cursor: '2026-01-01|bb' });
  assert.deepEqual(ghost.items.map(x => x.id), ['c', 'd', 'a', 'e']);

  // Cursor pair belonging to another tenant still positions correctly.
  const otherCursor = handler.list({ tenant: 'a', limit: 10, cursor: '2026-01-01|z' });
  assert.deepEqual(otherCursor.items.map(x => x.id), ['a', 'e']);

  // Filter-first: nextCursor only reflects matching tenant rows.
  const otherTenant = handler.list({ tenant: 'other', limit: 1 });
  assert.equal(otherTenant.nextCursor, null);

  // Invalid inputs.
  const bad = [
    { tenant: '', limit: 1 },
    { tenant: 'a', limit: 0 },
    { tenant: 'a', limit: 101 },
    { tenant: 'a', limit: 1.5 },
    { tenant: 'a', limit: NaN },
    { tenant: 'a', limit: 1, cursor: '' },
    { tenant: 'a', limit: 1, cursor: '2026-01-01' },
    { tenant: 'a', limit: 1, cursor: '2026-01-01|' },
