import { Order } from './types';

export interface OrderKey { createdAt: string; id: string }

function compareKeys(a: OrderKey, b: OrderKey): number {
  return a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  list(tenant: string): Order[] {
    return this.rows.filter(row => row.tenant === tenant).sort(compareKeys);
  }
  // Returns all orders for the tenant sorted by (createdAt, id), restricted to
  // those strictly after `after`. The filter is applied before the key comparison,
  // and `after` is compared by value, so it does not need to refer to an existing row.
  listAfter(tenant: string, after?: OrderKey): Order[] {
    const filtered = this.rows.filter(row => row.tenant === tenant);
    const sorted = filtered.sort(compareKeys);
    return after === undefined ? sorted : sorted.filter(row => compareKeys(row, after) > 0);
  }
}
